import React, { useCallback, useEffect } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';
import { useDispatch, useSelector, useStore } from 'react-redux';

import { PageHeader, StickyScrollWithFilters } from 'components';
import { refreshCommercialResultsFilterData } from 'redux/slices/filters';
import { AppDispatch, RootState } from 'redux/types';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';

import { serializeCommercialPresetDriverSignature } from './commercialResultsFilterPreset';
import { resolveCommercialResultsRefreshTier } from './commercialResultsRefreshMeta';
import { KpiDrillDown } from './components/KpiDrillDown/KpiDrillDown';
import { COMMERCIAL_RESULTS_PAGE_NAME } from './constants';
import { useCommercialResultsQuickFilterApply } from './hooks/useCommercialResultsQuickFilterApply';
import { CR_WATERFALL_RESET_EVENT } from './hooks/useCommercialResultsWaterfallFilterSync/useCommercialResultsWaterfallFilterSync';

const richText = {
  b: (chunks: React.ReactNode) => <b>{chunks}</b>,
};

const FILTER_VISIBLE_FIELDS: string[] = [
  'zone',
  'country',
  'region',
  'channel',
  'pack_type',
  'brands',
  'sub_brands',
  'sku',
  'periods',
];

export const CommercialResults = () => {
  const { formatMessage } = useIntl();
  const dispatch = useDispatch<AppDispatch>();
  const store = useStore<RootState>();

  const commercialPage = useSelector(
    (state: RootState) => state.filters.pages[COMMERCIAL_RESULTS_PAGE_NAME],
  );

  const pageTitle = formatMessage({
    id: 'ValueCreation.CommercialResults.title',
  });

  // Drawer: refresh option lists when draft preset drivers change.
  useEffect(() => {
    if (commercialPage?.status !== 'loaded') {
      return;
    }
    dispatch(refreshCommercialResultsFilterData('form'));
  }, [
    commercialPage?.form?.brands,
    commercialPage?.form?.country,
    commercialPage?.form?.zone,
    commercialPage?.form?.region,
    commercialPage?.form?.channel,
    commercialPage?.form?.pack_type,
    commercialPage?.status,
    dispatch,
  ]);

  const applied = commercialPage?.applied;
  const appliedDriverSignature = applied
    ? serializeCommercialPresetDriverSignature(applied)
    : undefined;

  // Quick filters auto-apply: sync committed preset when applied drivers change.
  useEffect(() => {
    if (commercialPage?.status !== 'loaded' || !applied) {
      return;
    }
    const appliedTier = resolveCommercialResultsRefreshTier(applied);
    const tierChanged =
      appliedTier !== commercialPage.lastCommercialRefreshTier;
    const driversChanged =
      appliedDriverSignature !==
      commercialPage.lastCommercialPresetDriverSignature;
    if (!tierChanged && !driversChanged) {
      return;
    }
    dispatch(refreshCommercialResultsFilterData('applied'));
  }, [
    applied,
    appliedDriverSignature,
    commercialPage?.lastCommercialRefreshTier,
    commercialPage?.lastCommercialPresetDriverSignature,
    commercialPage?.status,
    dispatch,
  ]);

  const handleQuickFilterValueChange = useCommercialResultsQuickFilterApply();

  const handleFilterReset = useCallback(() => {
    globalThis.dispatchEvent(new Event(CR_WATERFALL_RESET_EVENT));

    const page = store.getState().filters.pages[COMMERCIAL_RESULTS_PAGE_NAME];
    if (page?.status !== 'loaded') {
      return;
    }

    const appliedTier = resolveCommercialResultsRefreshTier(page.applied);
    if (appliedTier >= 2) {
      dispatch(refreshCommercialResultsFilterData('applied'));
    }
  }, [dispatch, store]);

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: COMMERCIAL_RESULTS_PAGE_NAME,
          visibleFields: FILTER_VISIBLE_FIELDS,
          onQuickFilterValueChange: handleQuickFilterValueChange,
          onReset: handleFilterReset,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/commercial-results',
              pageName: pageTitle,
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
        dataTestId="commercial-results-navigation"
      />

      <StyledGridContainer isResponsivePage>
        <StyledHomeContainer>
          <PageHeader
            title={pageTitle}
            subtitle={
              <FormattedMessage
                id="ValueCreation.CommercialResults.subtitle"
                values={richText}
              />
            }
            loading={false}
          />
          <KpiDrillDown />
        </StyledHomeContainer>
      </StyledGridContainer>
    </>
  );
};
